/* ===== Dù lượn nhiều người: định dạng tin khách ⇄ máy chủ (JSON) ===== */
import { multiParams } from './params';

export type ClientMsg =
  | { t: 'join'; name: string }
  | { t: 'pos'; x: number; y: number; z: number; yaw: number; bank: number }
  | { t: 'hb' }
  | { t: 'leave' };

export interface Flyer { slot: number; name: string }

// f: mỗi phần tử [slot, x, y, z, yaw, bank]
export type ServerMsg =
  | { t: 'lobby'; flyers: Flyer[] }
  | { t: 'joined'; slot: number }
  | { t: 'rejected'; why: 'full' | 'name' }
  | { t: 'pos'; f: number[][] }
  | { t: 'released' };

// Bỏ ký tự điều khiển và bidi/định dạng (giữ U+200D để ghép emoji), cắt khoảng trắng; rỗng hoặc quá nameMax grapheme → null
export function exSanitizeName(raw: string): string | null {
  if (typeof raw !== 'string') return null;
  const s = raw.replace(/[\p{Cc}\p{Cf}]/gu, c => (c === '\u200d' ? c : '')).trim();
  if (!s) return null;
  const seg = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
  let n = 0;
  for (const _ of seg.segment(s)) if (++n > multiParams.nameMax) return null;
  return s;
}

/* ===== Lọc tên tục (ngắn gọn, vi + en) ===== */
const BAD = ['dit', 'du ma', 'dm', 'dcm', 'dmm', 'cac', 'lon', 'buoi', 'dkm', 'vcl', 'vl', 'cutt', 'dam', 'fuck', 'shit', 'bitch', 'cunt', 'dick', 'pussy', 'asshole', 'nigger', 'nigga', 'fag', 'rape', 'sex'];

// Hạ chữ thường, bỏ dấu (đ → d), bỏ ký tự ngăn cách rồi tìm từ cấm
export function exIsBad(name: string): boolean {
  const flat = name.toLowerCase().replace(/đ/g, 'd').normalize('NFD').replace(/\p{M}/gu, '');
  const spaced = flat.replace(/[^a-z0-9]+/g, ' ').trim();
  const tight = spaced.replace(/ /g, '');
  const words = spaced.split(' ');
  return BAD.some(b => (b.length <= 3 ? words.includes(b) || tight === b : tight.includes(b.replace(/ /g, ''))));
}

/* ===== Phòng bầu trời chung: logic thuần, không phụ thuộc Cloudflare (Durable Object bọc ngoài) ===== */
